"""Embed the unmodified official Nuvio PNG in the Xbox executable."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
data = (root / "assets/nuvio-logo.png").read_bytes()
assert data.startswith(b"\x89PNG\r\n\x1a\n")
rows = ["    " + ",".join(str(b) for b in data[i:i+24]) + "," for i in range(0, len(data), 24)]
(root / "VisualStudio2010/src/NuvioLogoPng.h").write_text(
    "// Generated by tools/embed_logo.py from assets/nuvio-logo.png.\n"
    "// Official transparent mark: https://nuvio.tv/assets/Logo_1080x1080.png\n"
    "#ifndef NUVIO_LOGO_PNG_H\n#define NUVIO_LOGO_PNG_H\n"
    "static const unsigned char kNuvioLogoPng[] = {\n" + "\n".join(rows) + "\n};\n#endif\n",
    encoding="ascii")
print("Embedded official PNG:", len(data), "bytes")
